*{box-sizing:border-box} :root{--ink:#17232e;--muted:#75828a;--paper:#f4f1e8;--cream:#fffdf6;--line:#d8d6ca;--red:#e35f45;--teal:#4caaa0;--yellow:#f6cb68;--shadow:0 12px 40px #09111c36}body{margin:0;background:#111b28;color:var(--ink);font-family:Nunito,system-ui,sans-serif;min-height:100vh;background-image:radial-gradient(#fff1 1px,transparent 1px);background-size:18px 18px}button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #65c8bd;outline-offset:3px}.app{width:min(1200px,100%);min-height:100vh;margin:auto;padding:24px 34px 26px;position:relative}.topbar{height:42px;display:flex;align-items:center;justify-content:space-between;color:#e8e4d8}.brand{font-weight:900;letter-spacing:.11em;font-size:12px}.brand i{font-style:normal;color:var(--yellow)}.utility{display:flex;gap:8px}.utility button{background:#ffffff12;border:1px solid #ffffff27;color:#e8e4d8;border-radius:20px;padding:7px 12px;font-size:10px;font-weight:800;letter-spacing:.04em}.game-shell{position:relative;margin:10px auto 0;max-width:1060px;min-height:670px;background:var(--paper);border:1px solid #ffffff76;border-radius:22px;box-shadow:var(--shadow);overflow:hidden}.screen{display:none;min-height:670px}.screen.active{display:flex}.title-screen{position:relative;align-items:center;justify-content:center;text-align:center;padding:45px 28px;background:linear-gradient(125deg,#d9e7dc 0 49.8%,#f4e3d3 50%);overflow:hidden}.title-copy{z-index:2;width:100%;max-width:610px}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:.16em;color:#698078}.title-copy h1{font-size:clamp(54px,8vw,95px);line-height:.9;letter-spacing:-.08em;margin:15px 0 7px;font-weight:900;color:#263c3a}.title-copy h1 span{display:block;color:#e16b4f;font-size:.57em;letter-spacing:.07em;margin-top:8px}.subtitle{font-size:17px;font-weight:800;color:#52665e;margin:13px 0 29px}.version-picks{display:grid;grid-template-columns:1fr 1fr;gap:13px;max-width:550px;margin:auto}.version{position:relative;border:0;text-align:left;border-radius:14px;padding:19px 18px 15px 67px;min-height:94px;box-shadow:0 4px 0 #26382c22;transition:transform .16s,box-shadow .16s}.version:hover{transform:translateY(-3px);box-shadow:0 7px 0 #26382c22}.version.black{background:#263743;color:#fff}.version.white{background:#fffaf0;color:#3b4240}.version strong{display:block;font-size:14px;line-height:1.2}.version small{display:block;font:9px 'DM Mono',monospace;letter-spacing:.1em;margin-top:9px;opacity:.65}.version-mark{position:absolute;left:19px;top:24px;font-size:31px;color:#edc96d}.title-note{font-size:12px;color:#597168;margin-top:20px}.title-art{position:absolute;inset:0;pointer-events:none}.starter-portrait{position:absolute;width:135px;height:135px;border:6px solid #fff9;border-radius:50%;box-shadow:0 7px 24px #17232e2b}.starter-portrait.bootin{left:7%;bottom:10%;transform:rotate(-9deg);background:#e8c99e}.starter-portrait.chewy{right:7%;top:12%;transform:rotate(8deg);background:#d5a77e}.title-doodle{position:absolute;right:5%;bottom:10%;font:10px 'DM Mono',monospace;line-height:1.6;letter-spacing:.12em;transform:rotate(8deg);color:#72766a}.star{position:absolute;color:#fff;font-size:32px}.s1{top:12%;left:18%}.s2{bottom:24%;right:19%;font-size:25px}.intro-screen{align-items:center;justify-content:center;gap:6%;padding:50px 9%;background:radial-gradient(ellipse at 30% 60%,#dce9df 0 22%,transparent 23%),#f7f3e7}.intro-stamp{position:absolute;top:30px;left:38px;font:10px 'DM Mono',monospace;letter-spacing:.14em;color:#7a877d}.intro-sprite{width:280px;height:280px;flex:none;border-radius:50%;background:#dfc798;box-shadow:inset 0 0 0 13px #fff8,0 15px 35px #48513b23;display:grid;place-items:center;position:relative}.intro-copy{max-width:380px}.intro-copy h2{font-size:38px;line-height:1.05;margin:12px 0}.intro-copy p{color:#697673;line-height:1.7;font-size:14px;min-height:72px}.primary{border:0;background:#e36a4e;color:white;border-radius:9px;padding:13px 19px;font-size:12px;font-weight:900;letter-spacing:.08em;box-shadow:0 4px 0 #ad4937;margin-top:14px}.primary span{font-size:17px;margin-left:12px}.game-screen{flex-direction:column;padding:23px 34px 14px;min-height:670px}.game-heading{height:50px;display:flex;align-items:center;justify-content:space-between}.game-heading .eyebrow{font-size:9px}.game-heading h2{margin:3px 0;font-size:20px}.encounter-count{font:9px 'DM Mono',monospace;color:#78837c;letter-spacing:.07em}.encounter-count b{color:#344c49;font-size:12px;margin-left:5px}.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:#e16b4f;margin-right:6px;box-shadow:0 0 0 4px #e16b4f22}.battlefield{height:355px;border:1px solid #c9cbbb;border-radius:13px;overflow:hidden;position:relative;background:#d9e4dc}.arena{position:absolute;inset:0;background:linear-gradient(#c9dcd4 0 57%,#d5d9c2 57% 100%)}.arena:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#f8e8c544,#fff0 22% 78%,#f8e8c544);pointer-events:none}.arena-sky{position:absolute;inset:0 0 42%;background:linear-gradient(180deg,#c8ded8,#e6e5d0)}.grill{position:absolute;right:5%;top:13%;width:195px;height:93px;background:linear-gradient(145deg,#9aa9a5,#44585a);border:5px solid #d4d7ca;border-radius:10px;box-shadow:0 8px 0 #5c6a5a55;transform:perspective(300px) rotateX(-8deg)}.grill-label{color:#e6e5d8;font:7px 'DM Mono',monospace;text-align:center;padding-top:5px;letter-spacing:.12em}.grill-bars{height:52px;margin:6px 9px;background:repeating-linear-gradient(90deg,#667773 0 7px,#bcc5b8 7px 10px);border-radius:4px}.arena-floor{position:absolute;left:-5%;right:-5%;bottom:-53px;height:200px;background:#d9d3b3;border-radius:50% 50% 0 0;border-top:4px solid #c1c49e}.enemy-platform,.player-platform{position:absolute;width:190px;height:39px;border-radius:50%;background:#a7b49c;bottom:80px;right:14%;box-shadow:inset 0 -7px #879c8c}.player-platform{width:220px;height:45px;left:11%;bottom:18px;background:#c3b48e;box-shadow:inset 0 -8px #a5987b}.monster{position:absolute;z-index:2;width:180px;height:170px;display:grid;place-items:center;font-size:100px;filter:drop-shadow(0 9px 5px #35402e44);transition:transform .25s}.monster.enemy{right:14%;bottom:94px}.monster.player{left:11%;bottom:24px;transform:scaleX(-1)}.monster.hit{animation:hit .35s}.monster.attack{animation:attack .35s}@keyframes hit{50%{transform:translateX(15px) rotate(8deg);filter:brightness(1.7)}}@keyframes attack{50%{transform:translate(40px,-12px) scale(1.08)}}.enemy-card,.player-card{position:absolute;z-index:3;left:25px;top:22px;background:#fffdf2eF;padding:12px 14px 10px;border-radius:10px;width:210px;box-shadow:0 4px 12px #3543351c}.player-card{left:auto;right:25px;top:auto;bottom:17px;width:215px}.card-head{display:flex;justify-content:space-between;align-items:center;font-size:13px}.card-head span{font:10px 'DM Mono',monospace;color:#758078}.type-row{font:8px 'DM Mono',monospace;letter-spacing:.13em;color:#c07445;margin-top:4px}.hp-track{height:7px;background:#e5e3d8;border-radius:8px;margin-top:8px;overflow:hidden}.hp-track i{display:block;height:100%;width:100%;background:#71b66e;border-radius:8px;transition:width .35s,background .3s}.hp-track i.mid{background:#e5b752}.hp-track i.low{background:#e16850}.hp-caption{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#8a928b;margin-top:4px}.hp-caption b{color:#394641}.status{height:13px;font:8px 'DM Mono',monospace;color:#c06848;margin-top:3px}.toy-anim{position:absolute;display:none;z-index:5;left:50%;top:45%;font-size:34px}.toy-anim.throw{display:block;animation:throw 1.5s ease-in-out}@keyframes throw{0%{transform:translate(-220px,100px) rotate(0)}40%{transform:translate(0,-100px) rotate(360deg)}70%{transform:translate(20px,0) rotate(720deg) scale(.8)}100%{transform:translate(0,0) rotate(1080deg) scale(1.1)}}.battle-bottom{display:grid;grid-template-columns:1fr 1.05fr;gap:12px;margin-top:12px;min-height:126px}.message-box{border:1px solid var(--line);border-radius:11px;background:#fffdf5;padding:14px 15px;position:relative}.message-box p{font-size:14px;font-weight:800;margin:3px 0}.message-icon{position:absolute;right:13px;top:12px;color:#e4bb5b}.message-sub{font-size:11px;color:#808a82;margin-top:7px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.actions button,.choices button{position:relative;border:1px solid #d4d2c7;background:#fffdf5;border-radius:9px;color:#293d3b;text-align:left;padding:9px 12px;font-weight:900;font-size:12px;box-shadow:0 2px 0 #d9d6c9;transition:.15s}.actions button:hover,.choices button:hover{border-color:#65a99a;transform:translateY(-1px)}.actions button span{font-size:15px;margin-right:7px;color:#d56d4e}.actions button small{position:absolute;right:10px;top:12px;color:#869089;font:9px 'DM Mono',monospace}.choices{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-content:center}.choices button{font-size:10px;line-height:1.35}.choices button em{font-style:normal;display:block;color:#849087;font:8px 'DM Mono',monospace;margin-top:4px}.choices.hidden{display:none}.game-footer{margin-top:auto;padding-top:11px;display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;color:#899188;letter-spacing:.08em}.game-footer b{color:#68756d}.modal{position:fixed;inset:0;background:#111b28b8;z-index:10;display:grid;place-items:center;padding:18px}.modal.hidden{display:none}.modal-panel{position:relative;background:#f8f5eb;border-radius:15px;width:min(560px,100%);max-height:85vh;overflow:auto;padding:26px;box-shadow:0 20px 70px #080f18aa}.modal-close{position:absolute;right:14px;top:9px;border:0;background:none;color:#66736c;font-size:27px}.modal-panel h2{margin:2px 0 4px;font-size:24px}.modal-panel .eyebrow{font-size:9px}.modal-list{display:grid;gap:9px;margin-top:18px}.party-row,.toy-row{display:flex;align-items:center;gap:12px;padding:11px;border:1px solid #dedace;background:#fffdf6;border-radius:10px}.party-row .mini{font-size:30px;width:42px;text-align:center}.party-info{flex:1}.party-info b{font-size:13px}.party-info small{display:block;color:#829087;font:9px 'DM Mono',monospace;margin-top:3px}.party-row button,.toy-row button{border:0;border-radius:7px;background:#e7eee6;padding:8px 10px;color:#344c49;font-size:10px;font-weight:900}.party-row button:disabled{opacity:.45}.toy-row .mini{font-size:25px;width:39px;text-align:center}.toy-row button{background:#e26c50;color:white;min-width:76px}.toy-row button:disabled{background:#d4d1c7;color:#888}.party-cards{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin:23px auto;max-width:570px}.party-cards div{background:#fffdf4;border:1px solid #ddd7c8;border-radius:10px;padding:10px;width:135px}.party-cards span{font-size:30px;display:block}.party-cards b{font-size:12px}.party-cards small{display:block;color:#849087;font:8px 'DM Mono',monospace;margin-top:5px}.ending-screen{align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:35px;background:radial-gradient(circle at center,#e5eddf,#f5eddf 70%)}.ending-icon{font-size:44px;color:#e4bb5b}.ending-screen h2{font-size:40px;margin:10px 0}.ending-screen>p{max-width:480px;color:#748078;line-height:1.7}.hidden{display:none!important}footer{display:flex;justify-content:space-between;margin:15px 2px;color:#ffffff70;font:8px 'DM Mono',monospace;letter-spacing:.12em}
/* original vector-like dog portraits */.dog-art{position:relative;width:100%;height:100%;overflow:hidden}.dog-art .body{position:absolute;left:22%;bottom:12%;width:58%;height:38%;background:#f5eee0;border-radius:48% 50% 35% 44%;border:3px solid #5b4332}.dog-art .head{position:absolute;left:33%;top:18%;width:43%;height:41%;background:#f7ede0;border:3px solid #604936;border-radius:48% 50% 44% 42%;z-index:2}.dog-art .ear{position:absolute;z-index:3;top:20%;width:17%;height:27%;background:#9e6949;border:2px solid #604936;border-radius:60% 45% 65% 45%;transform:rotate(-24deg)}.dog-art .ear.left{left:28%}.dog-art .ear.right{right:20%;transform:rotate(27deg)}.dog-art .patch{position:absolute;z-index:4;right:26%;top:32%;width:13%;height:18%;background:#9c6545;border-radius:50%}.dog-art .eye{position:absolute;z-index:5;top:36%;width:5%;height:6%;background:#292822;border-radius:50%}.dog-art .eye.left{left:42%}.dog-art .eye.right{right:35%}.dog-art .muzzle{position:absolute;z-index:5;left:47%;top:45%;width:17%;height:12%;background:#fff8e9;border-radius:50%}.dog-art .nose{position:absolute;z-index:6;left:54%;top:44%;width:7%;height:5%;background:#302c28;border-radius:50%}.dog-art .collar{position:absolute;z-index:6;left:28%;top:55%;width:45%;height:7%;background:#e87889;border-radius:8px;transform:rotate(4deg)}.dog-art.boots .boot{position:absolute;z-index:7;bottom:0;width:30%;height:29%;background:linear-gradient(90deg,#68442f,#a7774d);border:3px solid #472f24;border-radius:6px 8px 12px 12px}.dog-art.boots .boot.one{left:22%;transform:rotate(-8deg)}.dog-art.boots .boot.two{right:14%;transform:rotate(5deg)}.dog-art.boots .boot:after{content:"";position:absolute;inset:7px 5px;background:repeating-linear-gradient(180deg,transparent 0 7px,#e6cfaa 7px 9px,transparent 9px 13px)}.dog-art.chewy .head{background:#3e342c}.dog-art.chewy .body{background:#46382d}.dog-art.chewy .patch{background:#bd8151;left:38%;right:auto;top:47%;width:14%;height:12%}.dog-art.chewy .ear{background:#2d2521}.dog-art.chewy .collar{background:#4a9eb1}.dog-art.chewy .eye{top:38%}.dog-art.chewy .tongue{position:absolute;z-index:6;left:56%;top:53%;width:11%;height:17%;background:#ed7d8c;border-radius:0 0 50% 50%;transform:rotate(-12deg)}.dog-art.chewy .muzzle{background:#c78d60}.dog-art.chewy .nose{background:#1b1918}.dog-art.hotdog .body{left:9%;bottom:25%;width:82%;height:35%;background:linear-gradient(180deg,#d8843e,#b64924 60%,#933a27);border-radius:50% 46% 45% 44%;border:4px solid #8e4029;transform:rotate(-8deg)}.dog-art.hotdog .head{left:21%;top:9%;width:36%;height:41%;background:#322a27}.dog-art.hotdog .ear{top:12%;background:#332824}.dog-art.hotdog .patch{background:#bb8255}.dog-art.hotdog .collar{background:#4ba4b5;top:44%;left:20%;width:38%;height:6%}.dog-art.hotdog .bun{position:absolute;z-index:1;left:8%;bottom:19%;width:85%;height:45%;border:9px solid #f0c983;border-top:0;border-radius:15% 15% 43% 43%;transform:rotate(-8deg);background:transparent}.dog-art.hotdog .mustard{position:absolute;z-index:4;left:51%;top:51%;font-size:22px;color:#f5d735;transform:rotate(-12deg)}.dog-art.hotdog .charring{position:absolute;z-index:4;left:48%;top:45%;width:16%;height:12%;background:#543629;border-radius:50%;transform:rotate(-18deg)}
@media(max-width:760px){.app{padding:12px 12px 18px}.game-shell{margin-top:7px;min-height:calc(100dvh - 105px);border-radius:16px}.screen{min-height:calc(100dvh - 105px)}.title-screen{padding:35px 18px}.title-art .starter-portrait{width:85px;height:85px}.starter-portrait.bootin{left:-15px;bottom:8%}.starter-portrait.chewy{right:-16px;top:8%}.title-copy h1{font-size:62px}.version-picks{gap:8px}.version{padding:14px 8px 12px 45px;min-height:88px}.version-mark{left:12px;font-size:25px}.version strong{font-size:11px}.version small{font-size:7px}.title-doodle{right:3%;font-size:8px}.intro-screen{flex-direction:column;gap:20px;padding:50px 25px 24px;text-align:center}.intro-sprite{width:210px;height:210px}.intro-copy h2{font-size:30px}.intro-copy p{min-height:0}.game-screen{padding:17px 13px 12px;min-height:calc(100dvh - 105px)}.game-heading{height:48px}.game-heading h2{font-size:16px}.encounter-count{font-size:7px}.battlefield{height:clamp(310px,47vh,390px)}.grill{width:130px;height:75px;right:5%;top:10%}.grill-bars{height:39px}.enemy-platform{right:5%;bottom:76px;width:145px}.player-platform{left:1%;width:155px;bottom:21px}.monster{width:130px;height:130px;font-size:76px}.monster.enemy{right:4%;bottom:93px}.monster.player{left:0;bottom:28px}.enemy-card{left:9px;top:10px;width:165px;padding:9px}.player-card{right:9px;bottom:9px;width:170px;padding:9px}.battle-bottom{grid-template-columns:1fr;gap:8px;margin-top:8px}.message-box{padding:11px 12px;min-height:64px}.message-box p{font-size:12px}.message-sub{font-size:10px;margin-top:3px}.actions{gap:6px}.actions button{padding:8px;font-size:11px}.actions button small{top:10px}.choices{gap:6px}.choices button{padding:7px}.game-footer{font-size:7px;padding-top:8px}.modal-panel{padding:23px 17px}.ending-screen h2{font-size:31px}footer{font-size:7px}.intro-stamp{left:18px;top:19px}}@media(max-width:380px){.title-copy h1{font-size:53px}.version strong{font-size:10px}.monster{font-size:66px}.battlefield{height:300px}.enemy-card,.player-card{width:151px}.card-head{font-size:11px}}

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const toys=[{id:'ball',name:'Squeaky Tennis Ball',emoji:'🎾',mult:1,qty:10,desc:'1× catch rate · the trusty classic'},{id:'rope',name:'Rope Tug Toy',emoji:'🪢',mult:1.5,qty:4,desc:'1.5× catch rate · tough and chewy'},{id:'hydrant',name:'Plush Fire Hydrant',emoji:'🧸',mult:2,qty:2,desc:'2× catch rate · extra plush'},{id:'bone',name:'Golden Rawhide Bone',emoji:'🦴',mult:255,qty:1,desc:'255× catch rate · never misses'}];
const moves={stomp:{name:'Timberland Stomp',power:18,type:'physical',accuracy:95},glare:{name:'Side-Eye Glare',power:18,type:'psychic',accuracy:95},mustard:{name:'Mustard Squirt',power:12,type:'special',accuracy:95},spin:{name:'Roller Grill Spin',power:15,type:'fire',accuracy:95},beg:{name:'Snack Beg',power:0,type:'status',accuracy:100},bite:{name:'Noodle Nibble',power:13,type:'physical',accuracy:100},sizzle:{name:'Sizzle Dash',power:16,type:'fire',accuracy:90},bun:{name:'Bun Shield',power:0,type:'status',accuracy:100},char:{name:'Charcoal Chomp',power:21,type:'physical',accuracy:90},crunch:{name:'Smoke Puff',power:14,type:'fire',accuracy:95},paw:{name:'Paw Feint',power:12,type:'physical',accuracy:100}};
const species={bootin:{name:'Bootin',emoji:'🐶',kind:'bootin',type:'GOOD DOG',moves:['stomp','mustard','spin','beg'],baseHP:30,atk:14,def:12,rate:255},chewy:{name:'Chewy',emoji:'🐕',kind:'chewy',type:'GOOD DOG',moves:['glare','mustard','spin','beg'],baseHP:29,atk:14,def:13,rate:255},roller:{name:'Roller Dog',emoji:'🌭',kind:'hotdog',type:'FIRE · NORMAL',moves:['bite','sizzle','mustard','beg'],baseHP:26,atk:12,def:10,rate:170},mustard:{name:'Mustard Bun Dog',emoji:'🌭',kind:'mustard',type:'FIRE · CONDIMENT',moves:['sizzle','mustard','bun','bite'],baseHP:36,atk:15,def:14,rate:90},charred:{name:'Charred Grill Boss',emoji:'🌭',kind:'charred',type:'FIRE · NORMAL',moves:['char','crunch','sizzle','mustard'],baseHP:48,atk:17,def:23,rate:45}};
let G={version:null,party:[],active:0,wild:null,count:0,turn:false,menu:'actions',locked:false,busy:false,sound:true};
function makeMonster(key,level){let s=species[key];let max=s.baseHP+level*3;return{key,name:s.name,kind:s.kind,type:s.type,level,max,hp:max,atk:s.atk+level,def:s.def+level,moves:[...s.moves],status:null,sauced:0,toast:0,defDown:0,noFlee:0,exp:0}}
function dogHTML(kind){let classes='dog-art '+kind;return `<div class="${classes}"><div class="body"></div>${kind==='hotdog'||kind==='mustard'||kind==='charred'?'<div class="bun"></div>':''}<div class="head"></div><div class="ear left"></div><div class="ear right"></div><div class="patch"></div><div class="eye left"></div><div class="eye right"></div><div class="muzzle"></div><div class="nose"></div><div class="collar"></div>${kind==='boots'?'<div class="boot one"></div><div class="boot two"></div>':''}${kind==='chewy'?'<div class="tongue"></div>':''}${kind==='mustard'?'<div class="mustard">〰</div>':''}${kind==='charred'?'<div class="charring"></div>':''}</div>`}
function sprite(node,mon){node.innerHTML=dogHTML(mon.kind);node.setAttribute('aria-label',mon.name)}
function screen(id){$$('.screen').forEach(e=>e.classList.toggle('active',e.id===id))}
function say(text,sub=''){ $('#message').textContent=text;$('#messageSub').textContent=sub }
function selectedStarter(){return G.version==='black'?'bootin':'chewy'}
function startVersion(version){G.version=version;const starter=selectedStarter();let m=makeMonster(starter,5);G.party=[m];G.active=0;$('#introSprite').innerHTML=dogHTML(m.kind);$('#introHeading').textContent=`Meet ${m.name}!`;$('#introDesc').textContent=m.name==='Bootin'?'A brave little terrier with a big heart and even bigger boots. Bootin is all paws-on-the-ground courage, and always ready for a snack-time stomp.':'A clever black-and-tan side-eye specialist. Chewy may look unimpressed, but this loyal little pal is already on your team.';screen('intro')}
function begin(){screen('game');newEncounter(true)}
function newEncounter(initial=false){if(!G.party.length)return;G.busy=false;G.locked=false;G.turn=false;G.menu='actions';G.count++;let key=G.count%7===0?'charred':G.count%3===0?'mustard':'roller';let level=key==='charred'?Math.min(12,6+Math.floor(G.count/8)):key==='mustard'?Math.min(9,4+Math.floor(G.count/5)):Math.min(7,2+Math.floor(G.count/4));G.wild=makeMonster(key,level);$('#locationName').textContent=G.count%2?'The Midnight Kitchen':'Nostalgia Concession Stand';$('#count').textContent=String(G.count).padStart(2,'0');update();say(`${initial?'A wild':'Another wild'} ${G.wild.name} ${key==='roller'?'rolled':key==='mustard'?'bunned':'sizzled'} into the kitchen!`,'What will you do?');showActions()}
function update(){const e=G.wild,p=G.party[G.active];if(!e||!p)return;sprite($('#enemySprite'),e);sprite($('#playerSprite'),p);$('#enemyName').textContent=e.name;$('#enemyLevel').textContent='Lv. '+e.level;$('#enemyType').textContent=e.type;$('#playerName').textContent=p.name;$('#playerLevel').textContent='Lv. '+p.level;$('#playerType').textContent=p.type;bar('enemy',e);bar('player',p);$('#enemyStatus').textContent=statusText(e);$('#playerStatus').textContent=statusText(p);$('#partyCount').textContent=`${G.party.length}/6`;$('#toyCount').textContent=toys.reduce((n,t)=>n+t.qty,0)}
function bar(who,m){let pct=Math.max(0,m.hp/m.max*100),el=$(`#${who}Hp`);el.style.width=pct+'%';el.className=pct<25?'low':pct<50?'mid':'';$(`#${who}HpText`).textContent=`${m.hp} / ${m.max}`}
function statusText(m){return [m.status==='toasted'?'TOASTED':m.status==='sauced'?'SAUCED':'',m.defDown?'DEF ↓':'',m.noFlee?'SNACK BEG':''].filter(Boolean).join(' · ')}
function showActions(){G.menu='actions';$('#actions').classList.remove('hidden');$('#choices').classList.add('hidden');G.locked=false}
function openChoices(type){if(G.busy)return;G.menu=type;$('#actions').classList.add('hidden');const c=$('#choices');c.classList.remove('hidden');c.innerHTML='';if(type==='fight'){G.party[G.active].moves.forEach((id,i)=>{let m=moves[id],b=document.createElement('button');b.innerHTML=`${m.name}<em>${m.type.toUpperCase()} · ${m.power?m.power+' PWR':'STATUS'} · ${m.accuracy}% ACC</em>`;b.onclick=()=>attack(id);c.appendChild(b)});let back=document.createElement('button');back.textContent='← BACK';back.onclick=showActions;c.appendChild(back)}else if(type==='bag'){toys.forEach(t=>{let b=document.createElement('button');b.disabled=!t.qty||G.party.length>=6;b.innerHTML=`${t.emoji} ${t.name} <em>${t.desc} · x${t.qty}</em>`;b.onclick=()=>throwToy(t.id);c.appendChild(b)});let back=document.createElement('button');back.textContent='← BACK';back.onclick=showActions;c.appendChild(back)} }
function moveDamage(attacker,defender,id){let m=moves[id];if(m.power===0)return 0;let power=m.power,atk=attacker.atk,def=Math.max(1,defender.def-(defender.defDown?Math.ceil(defender.def*.45):0));if(id==='mustard'&&defender.status==='toasted')power=Math.floor(power*.75);let stab=(m.type==='fire'&&attacker.type.includes('FIRE'))?1.25:1;return Math.max(1,Math.floor((((2*attacker.level/5+2)*power*atk/def)/14+2)*(0.85+Math.random()*.15)*stab))}
function attack(id){if(G.busy)return;G.busy=true;G.locked=true;let p=G.party[G.active],e=G.wild,m=moves[id];$('#choices').classList.add('hidden');if(Math.random()*100>m.accuracy){say(`${p.name} used ${m.name}, but it missed!`);finishTurn();return}if(id==='beg'){e.defDown=2;e.noFlee=3;say(`${p.name} gave the saddest snack eyes! ${e.name}'s defense fell.`,'It looks too guilty to run away now.');update();setTimeout(finishTurn,700);return}let d=moveDamage(p,e,id);e.hp=Math.max(0,e.hp-d);animate($('#playerSprite'),'attack');animate($('#enemySprite'),'hit');if(id==='mustard'&&Math.random()<.30){e.status='sauced';e.sauced=3;say(`${p.name} squirted mustard for ${d} damage!`,'Sauced! Its accuracy fell; it is easier to catch.')}else if(id==='spin'&&Math.random()<.20){e.status='toasted';e.toast=3;say(`${p.name} spun into ${e.name} for ${d} damage!`,'Toasted! The burn makes it easier to catch.')}else say(`${p.name} used ${m.name}! ${d} damage.`);update();if(e.hp<=0){setTimeout(()=>winWild(),500);return}setTimeout(enemyTurn,750)}
function animate(el,name){el.classList.remove('hit','attack');void el.offsetWidth;el.classList.add(name);setTimeout(()=>el.classList.remove(name),400)}
function enemyTurn(){let p=G.party[G.active],e=G.wild;if(!p||!e)return;if(e.status==='toasted'){let d=Math.max(1,Math.floor(e.max*.055));e.hp=Math.max(1,e.hp-d);say(`${e.name} takes ${d} burn damage from the grill!`);update()}let choices=e.moves.filter(x=>moves[x].power>0),id=choices[Math.floor(Math.random()*choices.length)],m=moves[id];if(Math.random()*100>m.accuracy){say(`${e.name} tried ${m.name}, but it missed!`)}else{let d=moveDamage(e,p,id);p.hp=Math.max(0,p.hp-d);animate($('#playerSprite'),'hit');say(`${e.name} used ${m.name}! ${d} damage.`);update()}if(p.hp<=0){setTimeout(()=>faintPlayer(),550);return}if(e.noFlee>0)e.noFlee--;else if(G.count>2&&Math.random()<.08){say(`${e.name} scampered off with a snack!`);setTimeout(()=>newEncounter(),900);return}if(e.sauced>0&&--e.sauced===0&&e.status==='sauced')e.status=null;if(e.toast>0&&--e.toast===0&&e.status==='toasted')e.status=null;update();setTimeout(()=>{G.busy=false;G.locked=false;showActions();say(`${G.wild.name} is still ready to rumble!`,'Your turn. Choose an action.')},550)}
function finishTurn(){update();if(G.wild.hp<=0){winWild();return}setTimeout(enemyTurn,650)}
function faintPlayer(){let next=G.party.findIndex((p,i)=>i!==G.active&&p.hp>0);if(next>=0){G.active=next;update();say(`${G.party.find(next=>next.hp>0).name} jumps in to help!`);G.busy=false;G.locked=false;setTimeout(showActions,500)}else{G.party.forEach(p=>p.hp=Math.max(1,Math.floor(p.max*.5)));G.active=0;update();say('Your team caught its breath at the snack table.','Everyone recovered a little HP.');G.busy=false;setTimeout(showActions,500)}}
function winWild(){let e=G.wild;let xp=4+e.level*3;G.party[G.active].exp+=xp;say(`${e.name} is toast! ${G.party[G.active].name} earned ${xp} friendship XP.`,'A new wild snack is on the way.');G.busy=false;setTimeout(()=>newEncounter(),1400)}
function throwToy(id){if(G.busy)return;let t=toys.find(x=>x.id===id);if(!t||!t.qty)return;t.qty--;update();G.busy=true;G.locked=true;$('#choices').classList.add('hidden');let anim=$('#toyAnim');anim.textContent=t.emoji;anim.classList.remove('throw');void anim.offsetWidth;anim.classList.add('throw');let e=G.wild;let success=t.mult>=255?true:captureRoll(e,t.mult);say(`You tossed a ${t.name} at ${e.name}...`,'Bounce, bounce...');setTimeout(()=>{anim.classList.remove('throw');if(success){say(`Click! ${e.name} joined your party!`,'A new pal, ready for adventures.');if(G.party.length<6){e.hp=Math.max(1,e.hp);G.party.push(e);G.active=G.party.length-1}else say(`${e.name} was sent to the kennel!`);update();setTimeout(()=>newEncounter(),1300)}else{say(`${e.name} popped free!`,'The toy bounced away. Keep trying!');G.busy=false;setTimeout(enemyTurn,650)}},1500)}
function captureRoll(e,ball){let a=Math.floor(((3*e.max-2*e.hp)*species[e.key].rate)/(3*e.max)*ball);let status=e.status==='toasted'?2:e.status==='sauced'?1.5:1;a=Math.max(1,Math.min(255,Math.floor(a*status)));let shake=Math.pow(a/255,.25);for(let i=0;i<3;i++){if(Math.random()>shake)return false}return true}
function openParty(){if(G.busy)return;openModal(`<div class="eyebrow">YOUR TRUSTED COMPANIONS</div><h2>Party <span style="color:#8b968d;font-size:14px">${G.party.length} / 6</span></h2><p style="color:#7d8981;font-size:12px">Choose a pal to take the lead. Your active dog appears in battle.</p><div class="modal-list">${G.party.map((p,i)=>`<div class="party-row"><div class="mini">${dogHTML(p.kind)}</div><div class="party-info"><b>${p.name} ${i===G.active?'· LEAD':''}</b><small>LV ${p.level} · ${p.hp}/${p.max} HP · ${p.type}</small></div><button data-lead="${i}" ${p.hp<=0?'disabled':''}>${i===G.active?'ACTIVE':'LEAD'}</button></div>`).join('')}</div>`);$$('[data-lead]').forEach(b=>b.onclick=()=>{G.active=+b.dataset.lead;update();closeModal();say(`${G.party[G.active].name} is taking the lead!`,'Ready for a new adventure.');showActions()})}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}function closeModal(){$('#modal').classList.add('hidden')}
function run(){if(G.busy)return;G.busy=true;G.locked=true;if(G.wild.noFlee){say(`${G.wild.name} is too captivated by the snack eyes to let you leave!`);setTimeout(enemyTurn,650);return}if(Math.random()<.8){say('You made a clean getaway!','The kitchen can wait.');setTimeout(()=>newEncounter(),800)}else{say('Could not get away!');setTimeout(enemyTurn,600)}}
function endGame(){screen('ending');$('#endingTitle').textContent='You made it home!';$('#endingText').textContent=`You and ${G.party.map(p=>p.name).join(', ')} had a delicious little adventure. You made ${G.count} wild encounters and built a party full of good dogs.`;$('#endingParty').innerHTML=G.party.map(p=>`<div><span>${p.kind==='hotdog'?'🌭':'🐶'}</span><b>${p.name}</b><small>LV ${p.level} · ${p.hp}/${p.max} HP</small></div>`).join('')}
$$('.version').forEach(b=>b.onclick=()=>startVersion(b.dataset.version));$('#beginBtn').onclick=begin;$('#againBtn').onclick=()=>{G={version:null,party:[],active:0,wild:null,count:0,turn:false,menu:'actions',locked:false,busy:false,sound:true};toys.forEach((t,i)=>t.qty=[10,4,2,1][i]);screen('title')};$('#actions').addEventListener('click',e=>{let b=e.target.closest('button');if(!b||G.busy)return;let a=b.dataset.action;if(a==='fight')openChoices('fight');if(a==='bag')openChoices('bag');if(a==='party')openParty();if(a==='run')run()});$('#modal').addEventListener('click',e=>{if(e.target.id==='modal'||e.target.closest('.modal-close'))closeModal()});$('#resetBtn').onclick=()=>{if(confirm('Start a fresh adventure? Current progress will be lost.')){G.party=[];screen('title')}};$('#soundBtn').onclick=e=>{G.sound=!G.sound;e.target.textContent=G.sound?'♪ SOUND ON':'♪ SOUND OFF'};
window.addEventListener('keydown',e=>{if(!$('#game').classList.contains('active')||!$('#modal').classList.contains('hidden'))return;let buttons=[...($('#choices').classList.contains('hidden')?$('#actions'):$('#choices')).querySelectorAll('button:not(:disabled)')];if(!buttons.length)return;let n=parseInt(document.activeElement?.dataset?.nav||'-1');if(e.key==='ArrowRight'||e.key==='ArrowDown'){e.preventDefault();buttons[(n+1+buttons.length)%buttons.length].focus();buttons[(n+1+buttons.length)%buttons.length].dataset.nav=(n+1+buttons.length)%buttons.length}if(e.key==='ArrowLeft'||e.key==='ArrowUp'){e.preventDefault();buttons[(n-1+buttons.length)%buttons.length].focus();buttons[(n-1+buttons.length)%buttons.length].dataset.nav=(n-1+buttons.length)%buttons.length}if(e.key==='Enter'&&document.activeElement?.tagName==='BUTTON')document.activeElement.click();if(e.key==='Escape'&&!$('#choices').classList.contains('hidden'))showActions()});
// Add the title-card portraits and let the display frame the opponent sprite.
$('#bootinTitle').innerHTML=dogHTML('boots');$('#chewyTitle').innerHTML=dogHTML('chewy');

