 function moveDamage(attacker,defender,id){let m=moves[id];if(m.power===0)return 0;let power=m.power,atk=attacker.atk,def=Math.max(1,defender.def-(defender.defDown?Math.ceil(defender.def*.45):0));if(id==='mustard'&&defender.status==='toasted')power=Math.floor(power*.75);let stab=(m.type==='fire'&&attacker.type.includes('FIRE'))?1.25:1;return Math.max(1,Math.floor((((2*attacker.level/5+2)*power*atk/def)/14+2)*(0.85+Math.random()*.15)*stab))}
