9: function screen(id){$$('.screen').forEach(e=>e.classList.toggle('active',e.id===id))}
10: function say(text,sub=''){ $('#message').textContent=text;$('#messageSub').textContent=sub }
11: function selectedStarter(){return G.version==='black'?'bootin':'chewy'}
12: function startVersion(version){G.version=version;const starter=selectedStarter();let m=makeMonster(starter,5);G.party=[m];G.active=0;$('#introSprite').innerHTML=dogHTML(m.kind);$('#introHeading').textContent=`Meet ${m.name}!`;$('#introDesc').textContent=m.name==='Bootin'?'A brave little terrier with a big heart and even bigger boots. Bootin is all paws-on-the-ground courage, and always ready for a snack-time stomp.':'A clever black-and-tan side-eye specialist. Chewy may look unimpressed, but this loyal little pal is already on your team.';screen('intro')}
13: function begin(){screen('game');newEncounter(true)}
14: function newEncounter(initial=false){if(!G.party.length)return;G.busy=false;G.locked=false;G.turn=false;G.menu='actions';G.count++;let key=G.count%7===0?'charred':G.count%3===0?'mustard':'roller';let level=key==='charred'?Math.min(12,6+Math.floor(G.count/8)):key==='mustard'?Math.min(9,4+Math.floor(G.count/5)):Math.min(7,2+Math.floor(G.count/4));G.wild=makeMonster(key,level);$('#locationName').textContent=G.count%2?'The Midnight Kitchen':'Nostalgia Concession Stand';$('#count').textContent=String(G.count).padStart(2,'0');update();say(`${initial?'A wild':'Another wild'} ${G.wild.name} ${key==='roller'?'rolled':key==='mustard'?'bunned':'sizzled'} into the kitchen!`,'What will you do?');showActions()}
15: function update(){const e=G.wild,p=G.party[G.active];if(!e||!p)return;sprite($('#enemySprite'),e);sprite($('#playerSprite'),p);$('#enemyName').textContent=e.name;$('#enemyLevel').textContent='Lv. '+e.level;$('#enemyType').textContent=e.type;$('#playerName').textContent=p.name;$('#playerLevel').textContent='Lv. '+p.level;$('#playerType').textContent=p.type;bar('enemy',e);bar('player',p);$('#enemyStatus').textContent=statusText(e);$('#playerStatus').textContent=statusText(p);$('#partyCount').textContent=`${G.party.length}/6`;$('#toyCount').textContent=toys.reduce((n,t)=>n+t.qty,0)}
16: function bar(who,m){let pct=Math.max(0,m.hp/m.max*100),el=$(`#${who}Hp`);el.style.width=pct+'%';el.className=pct<25?'low':pct<50?'mid':'';$(`#${who}HpText`).textContent=`${m.hp} / ${m.max}`}
