18: function showActions(){G.menu='actions';$('#actions').classList.remove('hidden');$('#choices').classList.add('hidden');G.locked=false}
19: function openChoices(type){if(G.busy)return;G.menu=type;$('#actions').classList.add('hidden');const c=$('#choices');c.classList.remove('hidden');c.innerHTML='';if(type==='fight'){G.party[G.active].moves.forEach((id,i)=>{let m=moves[id],b=document.createElement('button');b.innerHTML=`${m.name}<em>${m.type.toUpperCase()}${m.power?` · ${m.power} PWR`:''} · ${m.accuracy}% ACC${id==='glare'&&G.party[G.active].key==='chewy'?' · 35% CONFUSE':''}</em>`;b.onclick=()=>attack(id);c.appendChild(b)});let back=document.createElement('button');back.textContent='← BACK';back.onclick=showActions;c.appendChild(back)}else if(type==='bag'){toys.forEach(t=>{let b=document.createElement('button');b.disabled=!t.qty||G.party.length>=6;b.innerHTML=`${t.emoji} ${t.name} <em>${t.desc} · x${t.qty}</em>`;b.onclick=()=>throwToy(t.id);c.appendChild(b)});let back=document.createElement('button');back.textContent='← BACK';back.onclick=showActions;c.appendChild(back)} }
