/* A walkable, touch-friendly route between battles. */
.overworld-screen{display:none;flex-direction:column;padding:25px 34px 16px;background:linear-gradient(180deg,#f6f1df,#e8ead5)}.overworld-screen.active{display:flex}.world-heading{display:flex;align-items:center;justify-content:space-between}.world-heading h2{margin:4px 0 0;font-size:27px;color:#294a3d}.world-stats{display:flex;gap:8px}.world-stats span{padding:9px 12px;border:1px solid #d5dbc4;border-radius:12px;background:#fffdf1;color:#748078;font:500 9px 'DM Mono',monospace;letter-spacing:.08em}.world-stats b{color:#314d3d;font-size:12px}.world-intro{margin:8px 0 12px;color:#727d70;font-size:12px}.world-board-wrap{display:flex;justify-content:center;align-items:center;padding:12px;border-radius:20px;background:#adc884;box-shadow:inset 0 0 0 5px #8cab68,0 8px 18px #364d2522}.world-board{display:grid;grid-template-columns:repeat(11,minmax(0,1fr));width:min(100%,660px);aspect-ratio:11/9;overflow:hidden;border:4px solid #668653;border-radius:10px;background:#b8d38c}.world-tile{position:relative;display:grid;place-items:center;min-width:0;min-height:0;background:#b9d48b;border:1px solid #ffffff19}.world-tile.path{background:#e8d49c;box-shadow:inset 0 0 0 2px #dfc587}.world-tile.path:after{content:'';position:absolute;inset:5px;border:1px dashed #c3a86e55;border-radius:40%}.world-tile.grass{background:linear-gradient(135deg,#a8ca75,#8db765)}.world-tile.grass:before{content:'✦';position:absolute;bottom:8%;left:18%;font-size:clamp(8px,1.3vw,13px);color:#e9efae;opacity:.85}.world-tile.grass:after{content:'〃';position:absolute;right:13%;top:5%;font-size:clamp(10px,1.8vw,18px);font-weight:900;color:#6b9b52;transform:rotate(25deg)}.world-tile.water{background:repeating-linear-gradient(160deg,#79bfd0 0 9px,#88cbd4 9px 15px)}.world-tile.tree{background:#597d50}.world-tile.tree:after{content:'🌳';font-size:clamp(14px,3vw,28px);filter:drop-shadow(0 2px 1px #253c2c55)}.world-tile.flower{background:#b8d38c}.world-tile.flower:after{content:'🌼';font-size:clamp(10px,2vw,18px)}.world-tile.sign{background:#e8d49c}.world-tile.sign:after{content:'🪧';font-size:clamp(12px,2.4vw,23px)}.world-player{position:absolute;z-index:2;inset:5%;display:grid;place-items:center;animation:player-bob .7s ease-in-out infinite alternate}.world-player svg{width:100%;height:100%;filter:drop-shadow(0 2px 2px #24362880)}@keyframes player-bob{to{transform:translateY(-3px)}}.world-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px auto 0;width:min(100%,660px)}.world-hint{display:flex;align-items:center;gap:10px;color:#53734a}.world-hint>span:first-child{display:grid;place-items:center;width:37px;height:37px;border-radius:12px;background:#d8e6bf;font-size:19px}.world-hint b,.world-hint small{display:block}.world-hint b{font-size:11px}.world-hint small{margin-top:2px;color:#7a8677;font-size:9px}.world-controls{display:flex;flex-direction:column;align-items:center;gap:4px}.world-controls>div{display:flex;gap:4px}.world-controls button{width:34px;height:29px;border:1px solid #aebd9d;border-radius:8px;background:#fffdf3;color:#4d6745;font-size:12px;box-shadow:0 2px 0 #c6cfb7;touch-action:manipulation;user-select:none}.world-controls button:active{transform:translateY(2px);box-shadow:none}.world-footer{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:10px;color:#849084;font:500 8px 'DM Mono',monospace}.world-footer b{color:#617563}.world-footer button{padding:7px 10px;border:1px solid #d5dbc4;border-radius:10px;background:#fffdf1;color:#4d6745;font-size:9px;font-weight:900}.world-battle-pop{animation:map-flash .5s ease}@keyframes map-flash{50%{filter:brightness(1.3)}}.hippo-badge{font-size:11px}
@media(max-width:760px){.overworld-screen{padding:18px 14px 12px;min-height:calc(100dvh - 105px)}.world-heading h2{font-size:21px}.world-intro{font-size:11px;margin:7px 0 10px}.world-board-wrap{padding:7px;border-radius:14px}.world-board{width:min(100%,560px);border-width:3px}.world-bottom{margin-top:10px}.world-footer{font-size:7px}.world-tile.tree:after{font-size:clamp(13px,3.8vw,25px)}}
@media(max-width:380px){.world-stats{gap:4px}.world-stats span{padding:7px 8px;font-size:8px}.world-board-wrap{padding:5px}.world-controls button{width:31px;height:27px}.world-hint small{max-width:145px}}

