const routeMap=['###########','#gg..##ggg#','#gg..##ggg#','#....gg...#','##..ggw..##','#gg......g#','#gg.##...g#','#.....ggg#','###########'];
const worldTiles={grass:'grass',path:'path',water:'water', '#':'tree'};
function begin(){G.world={x:5,y:7,steps:0,grassSteps:0};screen('overworld');renderWorld()}
function renderWorld(){let board=$('#worldBoard');if(!board)return;board.innerHTML='';routeMap.forEach((row,y)=>[...row].forEach((code,x)=>{let tile=document.createElement('div');tile.className=`world-tile ${worldTiles[code]||'path'}`;tile.setAttribute('role','gridcell');if(code==='#')tile.setAttribute('aria-label','Trees');if(x===G.world.x&&y===G.world.y){tile.innerHTML=`<div class="world-player" aria-label="You are here">${dogHTML(G.party[G.active]?.kind||'bootin')}</div>`}board.appendChild(tile)}));$('#worldSteps').textContent=String(G.world.steps).padStart(2,'0');$('#worldParty').textContent=G.party.length}
function moveWorld(direction){if(!$('#overworld').classList.contains('active'))return;let delta={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[direction];if(!delta)return;let x=G.world.x+delta[0],y=G.world.y+delta[1],code=routeMap[y]?.[x];if(!code||code==='#'||code==='w')return;G.world.x=x;G.world.y=y;G.world.steps++;if(code==='g')G.world.grassSteps++;renderWorld();if(code==='g'&&(Math.random()<.27||G.world.grassSteps>=6)){G.world.grassSteps=0;$('#worldBoard').classList.add('world-battle-pop');setTimeout(()=>newEncounter(false,rollSpecies()),220)}}
function rollSpecies(){let roll=Math.random();return roll<.38?'roller':roll<.65?'mustard':roll<.84?'hippo':'charred'}
function returnToWorld(){G.wild=null;G.busy=false;G.locked=false;screen('overworld');renderWorld()}
function newEncounter(initial=false,key=null){if(!G.party.length)return;G.busy=false;G.locked=false;G.turn=false;G.menu='actions';G.count++;key=key||rollSpecies();let level=key==='charred'?Math.min(12,5+Math.floor(G.count/5)):key==='mustard'?Math.min(9,3+Math.floor(G.count/4)):key==='hippo'?Math.min(9,4+Math.floor(G.count/4)):Math.min(7,2+Math.floor(G.count/4));G.wild=makeMonster(key,level);screen('game');$('#locationName').textContent='Mustard Meadow · Tall Grass';$('#count').textContent=String(G.count).padStart(2,'0');update();let intro=key==='hippo'?`${G.wild.name} waddled out of the grass with a big happy snort!`:key==='roller'?`${G.wild.name} rolled out of the grass!`:key==='mustard'?`${G.wild.name} popped out of the grass!`:`${G.wild.name} stomped out of the grass!`;say(`${initial?'A wild ':''}${intro}`,'What will you do?');showActions()}

