  Line 16: function renderWorld(){let board=$('#worldBoard');if(!board)return;board.innerHTML='';routeMap.forEach((row,y)=>[...row].forEach((code,x)=>{let tile=document.createElement('div');tile.className=`world-tile ${worldTiles[code]||'path'}`;tile.setAttribute('role','gridcell');if(code==='#')tile.setAttribute('aria-label','Trees');if(x===G.world.x&&y===G.world.y){tile.innerHTML=`<div class="world-player" aria-label="You are here">${dogHTML(G.party[G.active]?.kind||'bootin')}</div>`}board.appendChild(tile)}));$('#worldSteps').textContent=String(G.world.steps).padStart(2,'0');$('#worldParty').textContent=G.party.length}

  Line 17: function moveWorld(direction){if(!$('#overworld').classList.contains('active'))return;let delta={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[direction];if(!delta)return;let x=G.world.x+delta[0],y=G.world.y+delta[1],code=routeMap[y]?.[x];if(!code||code==='#'||code==='w')return;G.world.x=x;G.world.y=y;G.world.steps++;if(code==='g')G.world.grassSteps++;renderWorld();if(code==='g'&&(Math.random()<.27||G.world.grassSteps>=6)){G.world.grassSteps=0;$('#worldBoard').classList.add('world-battle-pop');setTimeout(()=>newEncounter(false,rollSpecies()),220)}}

  Line 19: function returnToWorld(){G.wild=null;G.busy=false;G.locked=false;screen('overworld');renderWorld()}

