content.text:
.game-screen{flex-direction:column;padding:23px 34px 14px;min-height:670px}}
.game-heading{height:50px;display:flex;align-items:center;justify-content:space-between}}
.game-heading .eyebrow{font-size:9px}}
.game-heading h2{margin:3px 0;font-size:20px}}
.battlefield{height:355px;border:1px solid #c9cbbb;border-radius:13px;overflow:hidden;position:relative;background:#d9e4dc}}
.battle-bottom{display:grid;grid-template-columns:1fr 1.05fr;gap:12px;margin-top:12px;min-height:126px}}
.message-box{border:1px solid var(--line);border-radius:11px;background:#fffdf5;padding:14px 15px;position:relative}}
.message-box p{font-size:14px;font-weight:800;margin:3px 0}}
.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}}
.actions button,.choices button{position:relative;border:1px solid #d4d2c7;background:#fffdf5;border-radius:9px;color:#293d3b;text-align:left;padding:9px 12px;font-weight:900;font-size:12px;box-shadow:0 2px 0 #d9d6c9;transition:.15s}}
.actions button:hover,.choices button:hover{border-color:#65a99a;transform:translateY(-1px)}}
.actions button span{font-size:15px;margin-right:7px;color:#d56d4e}}
.actions button small{position:absolute;right:10px;top:12px;color:#869089;font:9px 'DM Mono',monospace}}
.choices{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-content:center}}
.choices button{font-size:10px;line-height:1.35}}
.choices button em{font-style:normal;display:block;color:#849087;font:8px 'DM Mono',monospace;margin-top:4px}}
.choices.hidden{display:none}}
.game-footer{margin-top:auto;padding-top:11px;display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;color:#899188;letter-spacing:.08em}}
.game-footer b{color:#68756d}}
@media(max-width:760px){.app{padding:12px 12px 18px}}
.game-screen{padding:17px 13px 12px;min-height:calc(100dvh - 105px)}}
.game-heading{height:48px}}
.game-heading h2{font-size:16px}}
.battlefield{height:clamp(310px,47vh,390px)}}
.battle-bottom{grid-template-columns:1fr;gap:8px;margin-top:8px}}
.message-box{padding:11px 12px;min-height:64px}}
.message-box p{font-size:12px}}
.actions{gap:6px}}
.actions button{padding:8px;font-size:11px}}
.actions button small{top:10px}}
.choices{gap:6px}}
.choices button{padding:7px}}
.game-footer{font-size:7px;padding-top:8px}}
@media(max-width:380px){.title-copy h1{font-size:53px}}
.battlefield{height:300px}}

