29: function enemyTurn(){let p=G.party[G.active],e=G.wild;if(!p||!e)return;if(e.status==='toasted'){let d=Math.max(1,Math.floor(e.max*.055));e.hp=Math.max(1,e.hp-d);say(`${e.name} takes ${d} burn damage from the grill!`);update()}let confused=e.confused>0&&Math.random()<.33;if(confused){let d=Math.max(1,Math.floor((((2*e.level/5+2)*40*e.atk/Math.max(1,e.def))/14)+2));e.hp=Math.max(0,e.hp-d);say(`${e.name} is confused and bonks itself for ${d} damage!`);animate($('#enemySprite'),'hit')}else{let choices=e.moves.filter(x=>moves[x].power>0),id=choices[Math.floor(Math.random()*choices.length)],m=moves[id],accuracy=m.accuracy*(e.status==='sauced'?.70:1);if(Math.random()*100>accuracy){say(`${e.name} tried ${m.name}, but it missed!`)}else{let d=moveDamage(e,p,id);p.hp=Math.max(0,p.hp-d);animate($('#playerSprite'),'hit');say(`${e.name} used ${m.name}! ${d} damage.`);update()}}if(e.confused>0)e.confused--;if(e.hp<=0){setTimeout(()=>winWild(),550);return}if(p.hp<=0){setTimeout(()=>faintPlayer(),550);return}if(e.noFlee>0)e.noFlee--;else if(G.count>2&&Math.random()<.08){say(`${e.name} scampered off into the grass!`);setTimeout(returnToWorld,900);return}if(e.sauced>0&&--e.sauced===0&&e.status==='sauced')e.status=null;if(e.toast>0&&--e.toast===0&&e.status==='toasted')e.status=null;update();setTimeout(()=>{G.busy=false;G.locked=false;showActions();say(`${G.wild.name} is still ready to rumble!`,'Your turn. Choose an action.')},550)}
