32: function winWild(){let e=G.wild;let xp=4+e.level*3;G.party[G.active].exp+=xp;say(`${e.name} is toast! ${G.party[G.active].name} earned ${xp} friendship XP.`,'Back to exploring Mustard Meadow!');G.busy=false;setTimeout(returnToWorld,1100)}
